(1766768, 240043, 18799, '<td valign="top">Nice job - this works very well.  Your composition and lighting are great.   9</td>', 'Nice job - this works very well.  Your composition and lighting are great.   9', '2005-10-07 00:45:34.000000', NULL, 1),
(1766770, 237953, 18799, '<td valign="top">Could be a little larger and a little sharper</td>', 'Could be a little larger and a little sharper', '2005-10-07 00:46:43.000000', NULL, 1),
