(1767230, 240542, 29474, '<td valign="top">I think that the red distracts from the effect of this picture. Something black / white / silver may have been better.</td>', 'I think that the red distracts from the effect of this picture. Something black / white / silver may have been better.', '2005-10-07 06:48:40.000000', NULL, 1),
(1767240, 240173, 22517, '<td valign="top">Well done, great model and colors.</td>', 'Well done, great model and colors.', '2005-10-07 06:53:39.000000', NULL, 1),
