(1768316, 238499, 43404, '<td valign="top">Really sharp photo, doesn''t meet the challenge though.</td>', 'Really sharp photo, doesn''t meet the challenge though.', '2005-10-07 18:22:26.000000', NULL, 1),
(1768325, 240386, 43404, '<td valign="top">I would have liked this better without the orange and blue, that would have fit the challenge better. Great idea though :)</td>', 'I would have liked this better without the orange and blue, that would have fit the challenge better. Great idea though :)', '2005-10-07 18:23:37.000000', NULL, 1),
(1768327, 240139, 43404, '<td valign="top">Great idea, meets challenge.</td>', 'Great idea, meets challenge.', '2005-10-07 18:24:14.000000', NULL, 1),
(1768346, 237962, 18339, '<td valign="top">Great composition, the colors are a little off and washed out.</td>', 'Great composition, the colors are a little off and washed out.', '2005-10-07 18:29:49.000000', NULL, 1),
(1768352, 240304, 18339, '<td valign="top">Cute kid, not sure where complementary color is.</td>', 'Cute kid, not sure where complementary color is.', '2005-10-07 18:32:26.000000', NULL, 1),
(1768364, 240531, 18339, '<td valign="top">I''m sure I''m not the first to say this but red and green are comlementary colors.  That said this is a nice shot, great composition.  A little soft in color and focus.</td>', 'I''m sure I''m not the first to say this but red and green are comlementary colors.  That said this is a nice shot, great composition.  A little soft in color and focus.', '2005-10-07 18:38:13.000000', NULL, 1),
(1768368, 237550, 18339, '<td valign="top">Needs a little more depth of field and softer light source.  Interesting composition.</td>', 'Needs a little more depth of field and softer light source.  Interesting composition.', '2005-10-07 18:40:15.000000', NULL, 1),
(1768374, 239700, 18339, '<td valign="top">Would be a great shot if focus was sharper and the colors (green) were more apparent.</td>', 'Would be a great shot if focus was sharper and the colors (green) were more apparent.', '2005-10-07 18:46:28.000000', NULL, 1),
