(1770641, 240484, 19936, '<td valign="top">Simple and sweet.  Great composition.</td>', 'Simple and sweet.  Great composition.', '2005-10-08 20:20:47.000000', NULL, 1),
(1770643, 240273, 42005, '<td valign="top">Outside of thinking this is a well focused and lit photograph which surely meets the challenge, it made me go out and purchase fresh red peppers and stuff them for dinner,  Great work.</td>', 'Outside of thinking this is a well focused and lit photograph which surely meets the challenge, it made me go out and purchase fresh red peppers and stuff them for dinner,  Great work.', '2005-10-08 20:22:31.000000', NULL, 1),
