INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1770751, 239644, 44575, '<td valign="top">Not sure how this meets the challenge.</td>', 'Not sure how this meets the challenge.', '2005-10-08 23:00:25.000000', NULL, 1),
