(1770753, 240350, 44575, '<td valign="top">Beautiful!  I love the richness of the colors, and the details on the clouds.   The wingtip anchors the whole image, IMO.</td>', 'Beautiful!  I love the richness of the colors, and the details on the clouds.   The wingtip anchors the whole image, IMO.', '2005-10-08 23:01:26.000000', NULL, 1),
(1770754, 240547, 44575, '<td valign="top">Doesn''t really meet challenge.</td>', 'Doesn''t really meet challenge.', '2005-10-08 23:02:19.000000', NULL, 1),
