(1774380, 240440, 34194, '<td valign="top">I like the subject but it''s a bit busy complementary color-wise.</td>', 'I like the subject but it''s a bit busy complementary color-wise.', '2005-10-10 15:43:10.000000', NULL, 1),
(1774386, 240452, 34194, '<td valign="top">a little dark and dull but interesting none the less</td>', 'a little dark and dull but interesting none the less', '2005-10-10 15:47:57.000000', NULL, 1),
(1774389, 238183, 34194, '<td valign="top">Complementary shades of gray?</td>', 'Complementary shades of gray?', '2005-10-10 15:49:50.000000', NULL, 1),
(1774394, 238133, 34194, '<td valign="top">focus seems a bit off...</td>', 'focus seems a bit off...', '2005-10-10 15:52:25.000000', NULL, 1),
(1774399, 240529, 34194, '<td valign="top">cool lighting</td>', 'cool lighting', '2005-10-10 15:55:24.000000', NULL, 1),
